// hooks/useOnboardingAgent.ts
import { useState, useCallback } from 'react';

export interface UICommand {
  action: 'navigate' | 'update' | 'validate' | 'show_error';
  component: string;
  props: Record<string, any>;
}

export interface OnboardingState {
  current_step: number;
  step_name: string;
  progress: number;
  is_complete: boolean;
}

export interface AgentResponse {
  text: string;
  ui_commands: UICommand[];
  onboarding_state: OnboardingState;
}

export interface UseOnboardingAgentReturn {
  sendAction: (action: string, data?: Record<string, any>) => Promise<AgentResponse>;
  isLoading: boolean;
  error: string | null;
}

export const useOnboardingAgent = (agentUrl: string = 'http://localhost:8083'): UseOnboardingAgentReturn => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const sendAction = useCallback(async (
    action: string,
    data: Record<string, any> = {}
  ): Promise<AgentResponse> => {
    setIsLoading(true);
    setError(null);

    try {
      const payload = {
        action,
        data,
        timestamp: new Date().toISOString()
      };

      const response = await fetch(`${agentUrl}/process`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: {
            parts: [{
              text: JSON.stringify(payload)
            }]
          }
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();

      // Parse the agent's response
      const artifactText = result.artifacts?.[0]?.parts?.[0]?.text;
      if (!artifactText) {
        throw new Error('Invalid response format');
      }

      const agentResponse: AgentResponse = JSON.parse(artifactText);
      return agentResponse;

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error occurred';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [agentUrl]);

  return { sendAction, isLoading, error };
};
